define({"topics":[{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_65.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e251017","topics":[]},{"title":"Removing the Gen1 gradient filter","shortdesc":"<p class=\"shortdesc\">Follow this procedure to remove a Gen1 gradient filter - either the MNS-specific model or the non-MNS model.<\/p>","href":"t_RemovingTheGen1GradientFilter.html","attributes":{"data-id":"id_2006214"},"menu":{"hasChildren":false},"tocID":"id_2006214-d46e251121","topics":[]},{"title":"Installing the Gen1 gradient filter","shortdesc":"<p class=\"shortdesc\">Follow this procedure to install a Gen1 gradient filter - either the MNS-specific model or the non-MNS model.<\/p>","href":"t_InstallingTheGen1GradientFilter.html","attributes":{"data-id":"id_2006215"},"menu":{"hasChildren":false},"tocID":"id_2006215-d46e251225","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_66.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e251329","topics":[]},{"title":"Doing DQA calibration","shortdesc":"<p class=\"shortdesc\">The DQA tool determines proper gradient polarity and proper gradient wiring by scanning a series of axial and coronal images of the DQA III phantom.<\/p>","href":"t_UsingtheDQAIICalibrationTool_5.html","attributes":{"data-id":"id_2001635"},"menu":{"hasChildren":false},"tocID":"id_2001635-d46e251434","topics":[]},{"title":"Doing the System Performance Test (SPT) ","shortdesc":"<p class=\"shortdesc\">The system performance test (SPT) automatically executes Eddy Current Check, SNR, Stability, and Coherent Noise tests. To do SPT in PM mode, you must launch SPT from the PM Assist menu.<\/p>","href":"t_SystemPerformanceTestSPTFullMode_2.html","attributes":{"data-id":"id_2003328"},"menu":{"hasChildren":true},"tocID":"id_2003328-d46e251539","next":"id_2003328-d46e251539"},{"title":"Doing the EPI White Pixel test (Full mode)","shortdesc":"<p class=\"shortdesc\">This procedure uses echo planar image (EPI) scans and the raw data mode of recon to analyze the raw data for white pixel artifacts. These raw data artifacts can exhibit themselves as corduroy artifacts in images.<\/p>","href":"t_DoingTheEPIWhitePixelTest_FullMode_2.html","attributes":{"data-id":"id_2001628"},"menu":{"hasChildren":true},"tocID":"id_2001628-d46e251853","next":"id_2001628-d46e251853"},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_99.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e252059","topics":[]}]});